#include <bits/stdc++.h>
using namespace std;
struct TreeNode{int val;TreeNode*left=nullptr,*right=nullptr;explicit TreeNode(int x):val(x){}};
TreeNode* buildTreeLevelOrder(const vector<optional<int>>&a){if(a.empty()||!a[0])return nullptr;TreeNode*r=new TreeNode(*a[0]);queue<TreeNode*>q;q.push(r);size_t i=1;while(i<a.size()&&!q.empty()){auto*u=q.front();q.pop();if(i<a.size()&&a[i])u->left=new TreeNode(*a[i]),q.push(u->left);++i;if(i<a.size()&&a[i])u->right=new TreeNode(*a[i]),q.push(u->right);++i;}return r;}
vector<optional<int>> treeToLevelOrder(TreeNode*r){vector<optional<int>>a;if(!r)return a;queue<TreeNode*>q;q.push(r);while(!q.empty()){auto*u=q.front();q.pop();if(u){a.push_back(u->val);q.push(u->left);q.push(u->right);}else a.push_back(nullopt);}while(!a.empty()&&!a.back())a.pop_back();return a;}
void preorderRec(TreeNode*r,vector<int>&a){if(!r)return;a.push_back(r->val);preorderRec(r->left,a);preorderRec(r->right,a);}void inorderRec(TreeNode*r,vector<int>&a){if(!r)return;inorderRec(r->left,a);a.push_back(r->val);inorderRec(r->right,a);}void postorderRec(TreeNode*r,vector<int>&a){if(!r)return;postorderRec(r->left,a);postorderRec(r->right,a);a.push_back(r->val);}
vector<int> preorderIter(TreeNode*r){vector<int>a;if(!r)return a;stack<TreeNode*>s;s.push(r);while(!s.empty()){auto*u=s.top();s.pop();a.push_back(u->val);if(u->right)s.push(u->right);if(u->left)s.push(u->left);}return a;}
vector<int> inorderIter(TreeNode*r){vector<int>a;stack<TreeNode*>s;auto*u=r;while(u||!s.empty()){while(u)s.push(u),u=u->left;u=s.top();s.pop();a.push_back(u->val);u=u->right;}return a;}
vector<int> postorderTwoStacks(TreeNode*r){vector<int>a;if(!r)return a;stack<TreeNode*>s1,s2;s1.push(r);while(!s1.empty()){auto*u=s1.top();s1.pop();s2.push(u);if(u->left)s1.push(u->left);if(u->right)s1.push(u->right);}while(!s2.empty())a.push_back(s2.top()->val),s2.pop();return a;}
vector<int> postorderOneStack(TreeNode*r){vector<int>a;stack<TreeNode*>s;TreeNode*cur=r,*last=nullptr;while(cur||!s.empty()){if(cur)s.push(cur),cur=cur->left;else{auto*peek=s.top();if(peek->right&&last!=peek->right)cur=peek->right;else{a.push_back(peek->val);last=peek;s.pop();}}}return a;}
vector<int> morrisInorder(TreeNode*r){vector<int>a;while(r){if(!r->left)a.push_back(r->val),r=r->right;else{TreeNode*p=r->left;while(p->right&&p->right!=r)p=p->right;if(!p->right)p->right=r,r=r->left;else p->right=nullptr,a.push_back(r->val),r=r->right;}}return a;}
vector<int> morrisPreorder(TreeNode*r){vector<int>a;while(r){if(!r->left)a.push_back(r->val),r=r->right;else{TreeNode*p=r->left;while(p->right&&p->right!=r)p=p->right;if(!p->right)a.push_back(r->val),p->right=r,r=r->left;else p->right=nullptr,r=r->right;}}return a;}
vector<vector<int>> levelOrder(TreeNode*r){vector<vector<int>>a;if(!r)return a;queue<TreeNode*>q;q.push(r);while(!q.empty()){int n=q.size();vector<int>l;while(n--){auto*u=q.front();q.pop();l.push_back(u->val);if(u->left)q.push(u->left);if(u->right)q.push(u->right);}a.push_back(move(l));}return a;}
vector<int> levelOrderFlat(TreeNode*r){vector<int>a;for(auto&l:levelOrder(r))a.insert(a.end(),l.begin(),l.end());return a;}vector<int> reverseLevelOrder(TreeNode*r){auto a=levelOrderFlat(r);reverse(a.begin(),a.end());return a;}
int maxDepth(TreeNode*r){return r?1+max(maxDepth(r->left),maxDepth(r->right)):0;}int minDepth(TreeNode*r){if(!r)return 0;if(!r->left)return 1+minDepth(r->right);if(!r->right)return 1+minDepth(r->left);return 1+min(minDepth(r->left),minDepth(r->right));}int countNodes(TreeNode*r){return r?1+countNodes(r->left)+countNodes(r->right):0;}int countLeaves(TreeNode*r){if(!r)return 0;if(!r->left&&!r->right)return 1;return countLeaves(r->left)+countLeaves(r->right);}long long sumTree(TreeNode*r){return r?r->val+sumTree(r->left)+sumTree(r->right):0;}int maximumValue(TreeNode*r){if(!r)return INT_MIN;return max({r->val,maximumValue(r->left),maximumValue(r->right)});}
bool sameTree(TreeNode*a,TreeNode*b){if(!a||!b)return a==b;return a->val==b->val&&sameTree(a->left,b->left)&&sameTree(a->right,b->right);}bool symmetricHelper(TreeNode*a,TreeNode*b){if(!a||!b)return a==b;return a->val==b->val&&symmetricHelper(a->left,b->right)&&symmetricHelper(a->right,b->left);}bool isSymmetric(TreeNode*r){return !r||symmetricHelper(r->left,r->right);}bool isSubtree(TreeNode*r,TreeNode*s){if(!s)return true;if(!r)return false;return sameTree(r,s)||isSubtree(r->left,s)||isSubtree(r->right,s);}
int balancedHeight(TreeNode*r){if(!r)return 0;int l=balancedHeight(r->left);if(l<0)return -1;int h=balancedHeight(r->right);if(h<0||abs(l-h)>1)return -1;return 1+max(l,h);}bool isBalanced(TreeNode*r){return balancedHeight(r)>=0;}int diameter(TreeNode*r,int&h){if(!r){h=0;return 0;}int lh=0,rh=0;int ld=diameter(r->left,lh),rd=diameter(r->right,rh);h=1+max(lh,rh);return max({ld,rd,lh+rh});}int diameterOfTree(TreeNode*r){int h=0;return diameter(r,h);}
bool hasPathSum(TreeNode*r,long long target){if(!r)return false;target-=r->val;if(!r->left&&!r->right)return target==0;return hasPathSum(r->left,target)||hasPathSum(r->right,target);}void rootLeafPaths(TreeNode*r,vector<int>&path,vector<vector<int>>&out){if(!r)return;path.push_back(r->val);if(!r->left&&!r->right)out.push_back(path);else rootLeafPaths(r->left,path,out),rootLeafPaths(r->right,path,out);path.pop_back();}vector<vector<int>> allRootLeafPaths(TreeNode*r){vector<vector<int>>o;vector<int>p;rootLeafPaths(r,p,o);return o;}
long long maxPathSumHelper(TreeNode*r,long long&best){if(!r)return 0;long long l=max(0LL,maxPathSumHelper(r->left,best)),rr=max(0LL,maxPathSumHelper(r->right,best));best=max(best,l+rr+r->val);return r->val+max(l,rr);}long long maxPathSum(TreeNode*r){if(!r)return 0;long long b=LLONG_MIN;maxPathSumHelper(r,b);return b;}long long sumRootLeafNumbers(TreeNode*r,long long cur=0){if(!r)return 0;cur=cur*10+r->val;if(!r->left&&!r->right)return cur;return sumRootLeafNumbers(r->left,cur)+sumRootLeafNumbers(r->right,cur);}
TreeNode* lca(TreeNode*r,TreeNode*p,TreeNode*q){if(!r||r==p||r==q)return r;auto*a=lca(r->left,p,q),*b=lca(r->right,p,q);return a&&b?r:(a?a:b);}TreeNode* lcaByValue(TreeNode*r,int a,int b){TreeNode*p=nullptr,*q=nullptr;function<void(TreeNode*)>f=[&](TreeNode*x){if(!x)return;if(x->val==a)p=x;if(x->val==b)q=x;f(x->left);f(x->right);};f(r);return p&&q?lca(r,p,q):nullptr;}
vector<int> rightSideView(TreeNode*r){vector<int>a;for(auto&l:levelOrder(r))if(!l.empty())a.push_back(l.back());return a;}vector<int> leftSideView(TreeNode*r){vector<int>a;for(auto&l:levelOrder(r))if(!l.empty())a.push_back(l.front());return a;}
vector<int> topView(TreeNode*r){if(!r)return {};map<int,int>m;queue<pair<TreeNode*,int>>q;q.push({r,0});while(!q.empty()){auto [u,d]=q.front();q.pop();if(!m.count(d))m[d]=u->val;if(u->left)q.push({u->left,d-1});if(u->right)q.push({u->right,d+1});}vector<int>a;for(auto [d,x]:m)a.push_back(x);return a;}vector<int> bottomView(TreeNode*r){if(!r)return {};map<int,int>m;queue<pair<TreeNode*,int>>q;q.push({r,0});while(!q.empty()){auto [u,d]=q.front();q.pop();m[d]=u->val;if(u->left)q.push({u->left,d-1});if(u->right)q.push({u->right,d+1});}vector<int>a;for(auto [d,x]:m)a.push_back(x);return a;}
vector<vector<int>> zigzagLevelOrder(TreeNode*r){auto a=levelOrder(r);for(int i=1;i<(int)a.size();i+=2)reverse(a[i].begin(),a[i].end());return a;}
int burningTreeTime(TreeNode*r,int target){if(!r)return -1;unordered_map<TreeNode*,TreeNode*>par;queue<TreeNode*>q;q.push(r);TreeNode*src=nullptr;par[r]=nullptr;while(!q.empty()){auto*u=q.front();q.pop();if(u->val==target)src=u;if(u->left)par[u->left]=u,q.push(u->left);if(u->right)par[u->right]=u,q.push(u->right);}if(!src)return -1;unordered_set<TreeNode*>vis{src};q.push(src);int time=-1;while(!q.empty()){int n=q.size();++time;while(n--){auto*u=q.front();q.pop();for(auto*v:{u->left,u->right,par[u]})if(v&&!vis.count(v))vis.insert(v),q.push(v);}}return time;}
string serialize(TreeNode*r){if(!r)return "#";return to_string(r->val)+","+serialize(r->left)+","+serialize(r->right);}TreeNode* deserialize(const string&s){stringstream ss(s);string t;function<TreeNode*()>f=[&](){if(!getline(ss,t,','))return (TreeNode*)nullptr;if(t=="#")return (TreeNode*)nullptr;auto*r=new TreeNode(stoi(t));r->left=f();r->right=f();return r;};return f();}
TreeNode* buildPreIn(const vector<int>&pre,const vector<int>&in){unordered_map<int,int>idx;for(int i=0;i<(int)in.size();++i)idx[in[i]]=i;int p=0;function<TreeNode*(int,int)>f=[&](int l,int r)->TreeNode*{if(l>r)return nullptr;int x=pre[p++],m=idx[x];auto*n=new TreeNode(x);n->left=f(l,m-1);n->right=f(m+1,r);return n;};return pre.empty()?nullptr:f(0,(int)in.size()-1);}TreeNode* buildInPost(const vector<int>&in,const vector<int>&post){unordered_map<int,int>idx;for(int i=0;i<(int)in.size();++i)idx[in[i]]=i;int p=(int)post.size()-1;function<TreeNode*(int,int)>f=[&](int l,int r)->TreeNode*{if(l>r)return nullptr;int x=post[p--],m=idx[x];auto*n=new TreeNode(x);n->right=f(m+1,r);n->left=f(l,m-1);return n;};return in.empty()?nullptr:f(0,(int)in.size()-1);}
// BST routines assume distinct keys.
TreeNode* bstSearch(TreeNode*r,int x){while(r&&r->val!=x)r=x<r->val?r->left:r->right;return r;}TreeNode* bstInsert(TreeNode*r,int x){if(!r)return new TreeNode(x);if(x<r->val)r->left=bstInsert(r->left,x);else if(x>r->val)r->right=bstInsert(r->right,x);return r;}TreeNode* bstInsertIterative(TreeNode*r,int x){if(!r)return new TreeNode(x);auto*u=r;while(true){if(x<u->val){if(!u->left){u->left=new TreeNode(x);break;}u=u->left;}else if(x>u->val){if(!u->right){u->right=new TreeNode(x);break;}u=u->right;}else break;}return r;}TreeNode* bstMin(TreeNode*r){if(!r)return nullptr;while(r->left)r=r->left;return r;}TreeNode* bstMax(TreeNode*r){if(!r)return nullptr;while(r->right)r=r->right;return r;}TreeNode* bstSuccessor(TreeNode*r,int x){TreeNode*ans=nullptr;while(r){if(r->val>x)ans=r,r=r->left;else r=r->right;}return ans;}TreeNode* bstPredecessor(TreeNode*r,int x){TreeNode*ans=nullptr;while(r){if(r->val<x)ans=r,r=r->right;else r=r->left;}return ans;}TreeNode* bstDelete(TreeNode*r,int x){if(!r)return nullptr;if(x<r->val)r->left=bstDelete(r->left,x);else if(x>r->val)r->right=bstDelete(r->right,x);else{if(!r->left){auto*t=r->right;delete r;return t;}if(!r->right){auto*t=r->left;delete r;return t;}auto*t=bstMin(r->right);r->val=t->val;r->right=bstDelete(r->right,t->val);}return r;}bool validBST(TreeNode*r,long long lo=LLONG_MIN,long long hi=LLONG_MAX){if(!r)return true;if(r->val<=lo||r->val>=hi)return false;return validBST(r->left,lo,r->val)&&validBST(r->right,r->val,hi);}int kthSmallestBST(TreeNode*r,int k){stack<TreeNode*>s;while(r||!s.empty()){while(r)s.push(r),r=r->left;r=s.top();s.pop();if(--k==0)return r->val;r=r->right;}return -1;}int kthLargestBST(TreeNode*r,int k){stack<TreeNode*>s;while(r||!s.empty()){while(r)s.push(r),r=r->right;r=s.top();s.pop();if(--k==0)return r->val;r=r->left;}return -1;}TreeNode* bstLCA(TreeNode*r,int a,int b){while(r){if(a<r->val&&b<r->val)r=r->left;else if(a>r->val&&b>r->val)r=r->right;else return r;}return nullptr;}TreeNode* sortedArrayToBST(const vector<int>&a,int l,int h){if(l>h)return nullptr;int m=l+(h-l)/2;auto*r=new TreeNode(a[m]);r->left=sortedArrayToBST(a,l,m-1);r->right=sortedArrayToBST(a,m+1,h);return r;}TreeNode* sortedArrayToBST(const vector<int>&a){return sortedArrayToBST(a,0,(int)a.size()-1);}
class MinHeap{vector<int>a;void down(int i){int n=a.size();while(2*i+1<n){int c=2*i+1;if(c+1<n&&a[c+1]<a[c])++c;if(a[i]<=a[c])break;swap(a[i],a[c]);i=c;}}public:MinHeap()=default;explicit MinHeap(vector<int>x):a(move(x)){for(int i=(int)a.size()/2-1;i>=0;--i)down(i);}void push(int x){a.push_back(x);int i=a.size()-1;while(i&&a[(i-1)/2]>a[i])swap(a[i],a[(i-1)/2]),i=(i-1)/2;}int top()const{return a.at(0);}int pop(){int x=top();a[0]=a.back();a.pop_back();if(!a.empty())down(0);return x;}bool empty()const{return a.empty();}};
class MaxHeap{priority_queue<int>q;public:void push(int x){q.push(x);}int top()const{return q.top();}int pop(){int x=q.top();q.pop();return x;}bool empty()const{return q.empty();}};
vector<int> heapifyMin(vector<int>a){make_heap(a.begin(),a.end(),greater<int>());return a;}int kthLargestHeap(vector<int>a,int k){if(k<1||k>(int)a.size())return -1;priority_queue<int,vector<int>,greater<int>>q;for(int x:a){q.push(x);if((int)q.size()>k)q.pop();}return q.top();}int kthSmallestHeap(vector<int>a,int k){if(k<1||k>(int)a.size())return -1;priority_queue<int>q;for(int x:a){q.push(x);if((int)q.size()>k)q.pop();}return q.top();}vector<int> topKFrequent(const vector<int>&a,int k){unordered_map<int,int>f;for(int x:a)++f[x];priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>>q;for(auto [x,c]:f){q.push({c,x});if((int)q.size()>k)q.pop();}vector<int>r;while(!q.empty())r.push_back(q.top().second),q.pop();return r;}
int kthSmallestSortedMatrix(const vector<vector<int>>&m,int k){using T=tuple<int,int,int>;priority_queue<T,vector<T>,greater<T>>q;for(int i=0;i<(int)m.size();++i)if(!m[i].empty())q.emplace(m[i][0],i,0);while(--k&& !q.empty()){auto [x,i,j]=q.top();q.pop();if(j+1<(int)m[i].size())q.emplace(m[i][j+1],i,j+1);}return q.empty()?-1:get<0>(q.top());}
struct TrieNode{array<TrieNode*,26>child{};bool end=false;};class Trie{TrieNode*root=new TrieNode();public:void insert(const string&s){auto*n=root;for(char c:s){int i=c-'a';if(!n->child[i])n->child[i]=new TrieNode();n=n->child[i];}n->end=true;}bool search(const string&s)const{auto*n=root;for(char c:s){n=n->child[c-'a'];if(!n)return false;}return n->end;}bool startsWith(const string&s)const{auto*n=root;for(char c:s){n=n->child[c-'a'];if(!n)return false;}return true;}string shortestRoot(const string&s)const{auto*n=root;string r;for(char c:s){n=n->child[c-'a'];if(!n)return s;r+=c;if(n->end)return r;}return s;}};
string replaceWordsWithTrie(const vector<string>&dict,const string&sentence){Trie t;for(auto&w:dict)t.insert(w);istringstream in(sentence);string w,out;while(in>>w){if(!out.empty())out+=' ';out+=t.shortestRoot(w);}return out;}
void recursiveTreeTemplate(TreeNode*r){if(!r)return;recursiveTreeTemplate(r->left);recursiveTreeTemplate(r->right);}vector<int> treeBFSTemplate(TreeNode*r){return levelOrderFlat(r);}
